 n->phase=Phase::Stopped;n->dispose();puts("Bus enrollment: independent Node/OpenSSL seal, device X25519 key, new origin with empty pairing, approval binding, rotate/revoke, tamper/wrong-key, rejection/expiry, reboot atomicity and secret-free wire results PASS");
